using System;using System.Linq;using System.IO;using Verse;using PlayableRecreation;using PRQA;
public static class Command{public static string Run(){int start=Find.TickManager.TicksGame;Host.Watch=()=>{if(Find.TickManager.TicksGame-start<150)return;var pair=(Pawn[])Host.State["pair"];var b=(Thing)Host.State["chess"];File.WriteAllText(Host.Root+"/seat-settled.txt",string.Join("\n",pair.Take(2).Select(p=>p+" pos="+p.Position+" seat="+p.CurJob?.targetC+" rotation="+p.Rotation.AsInt+" chair="+p.Position.GetEdifice(b.Map)?.def+" held="+TogetherMatch.ShouldHold(b,p))));Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;};Find.TickManager.CurTimeSpeed=TimeSpeed.Normal;return "Let both actors finish arrival/facing for 150 ticks.";}}
